def place(item, bins):
    eps = 1e-12
    k = 100
    counts = [0] * (k + 1)
    for r in bins:
        if r > 0.0:
            b = int(r * k)
            if b > k:
                b = k
            counts[b] += 1

    def bucket(x):
        b = int(x * k)
        return k if b > k else b

    new_res = 1.0 - item
    nb_new = bucket(new_res)
    best_score = 2 * counts[nb_new] + 1
    best_res = new_res
    best_i = len(bins)

    for i, r in enumerate(bins):
        if r + eps < item:
            continue
        res = r - item
        ob = bucket(r)
        nb = bucket(res)
        if ob == nb:
            score = 0
        else:
            score = 2 * (counts[nb] - counts[ob]) + 2
        if (score, res, i) < (best_score, best_res, best_i):
            best_score = score
            best_res = res
            best_i = i
    return best_i
